import Foundation
import KwipMLCore

/// Current assessment reading, composed only from public task/control metadata.
@MainActor enum LayerTopicLessonCopy {
    struct Copy {let purpose:String;let sources:String;let wiring:String;let controls:String;let question:String}
    static func task(_ operation:String)->Copy? {
        let guide=LessonAudienceGuide.make(operation:operation)
        if let t=EmbeddingBagLearningTask(rawValue:operation) {
            return .init(purpose:"An observation may contain a group of category IDs, such as the items in one basket. Embedding bag looks up each selected vector and combines the group into one vector rather than keeping a separate vector per item.",sources:"The checker supplies category IDs and, when enabled, real item weights, source lengths and packed-group boundaries. A vector is an ordered list of numbers. Packed offsets mark where each group begins; equal offsets can represent an empty group. These integer boundaries describe data, not settings to learn.",wiring:guide.steps[0],controls:guide.steps[1],question:"\(t.title): predict what happens when an item repeats or a group is empty. Why must a real item weight stay paired with its category ID? Which values are excluded by a padding row?")
        }
        if let t=ModuleCompositionLearningTask(rawValue:operation) {
            return .init(purpose:"A reusable Block groups connected calculations. Reusing a calculation is different from sharing its learned values: a private copy can have the same structure and independent weights.",sources:"This assessment starts with a supplied Block model and fixed context. Its nested editors hold the mathematical exercise's components; reading this lesson does not edit them. \(t == .buildReuse ? "Compare the supplied Block with its private copies, preserving the fixed sign reversal and subtraction." : "Compare a sequence, an ordered collection and a named collection. Stored child order/names and connected calculation order are separate properties.")",wiring:guide.steps[0],controls:guide.steps[1],question:"Why can identical structures produce different results after their private weights change? Which order is recorded in the container and which order is established by its connections?")
        }
        if let t=AttentionLearningTask(rawValue:operation) {
            let sources=t.sourceRoles.map {"- \($0): a supplied sequence role."}.joined(separator:"\n")
            let wiring=guide.steps[0]
            return .init(purpose:"A sequence position can use information from other allowed positions. Attention compares queries with keys and combines their associated values; a mask determines which comparisons are blocked. A query describes what a position is looking for, a key describes a source position, and a value carries its information. \(t.title) isolates that behavior rather than training a text generator.",sources:"The checker supplies these roles:\n"+sources+"\nA sequence has positions and features within each observation. A mask uses query position then source position: one blocks a connection and zero allows it. These masks are tensor data. Learned tables, where the task uses them, are supplied by the checker.",wiring:wiring,controls:t.controlInstructions,question:"Which positions may influence one result? Why must a blocked connection contribute nothing? Keep the mask's meaning separate from an ordinary score or a padding token ID.")
        }
        if let t=RecurrentLearningTask(rawValue:operation) {
            return .init(purpose:"Ordered measurements often need a summary of what came before. A recurrent layer updates a hidden state as it reads positions; a recurrent cell performs one such step. Hidden state is input/output data, while learned weights are the reusable calculation.",sources:"This task is \(t.title). Supplied source roles are \(t.sourceRoles.joined(separator:", ")). Whole sequences use time and feature directions inside each observation; a cell reads one feature vector. LSTM has separate hidden and cell memories. The checker supplies varied values and learned tables rather than asking you to train them.",wiring:guide.steps[0],controls:t.controlInstructions.replacingOccurrences(of:"Starting state to supplied",with:"Starting state to Use state connections").replacingOccurrences(of:"Choose relu for Behavior",with:"Choose Keep positive values for Behavior"),question:"Which output describes the final step, and which describes all sequence positions? Why must the starting hidden state remain separate from the learned weights? For LSTM, what extra information travels in cell memory?")
        }
        if let t=StatefulNormalizationLearningTask(rawValue:operation) {
            let grouping=t.componentID.hasPrefix("batch") ? "Batch compares each channel across observations and positions in the current group." : t.componentID.hasPrefix("instance") ? "Instance compares positions separately within each observation/channel." : "Group compares teams of channels within each observation."
            return .init(purpose:"Measurements on different scales can be difficult for later layers to use. Normalization compares a chosen group with its average/spread before applying optional learned scale and shift. Choosing that group is part of the model's meaning.",sources:"\(grouping) A channel is a separate measurement field, such as one feature map. This task is \(t.title). \(t.remembered ? "The checker runs supplied calibration groups to build remembered summaries, then checks evaluation without updating them." : "This task uses current-input summaries rather than claiming saved training statistics.") This model operation is separate from Preprocess learning statistics over a Training table.",wiring:guide.steps[0],controls:guide.steps[1].replacingOccurrences(of:"Use Moving for Averaging method",with:"Use Moving summary for Averaging method"),question:"Which other values can affect one normalized value? If the task remembers summaries, why must evaluation leave them unchanged? Distinguish a learned scale/shift from the measured group statistics.")
        }
        if let t=AdaptivePoolingLearningTask(rawValue:operation) {
            return .init(purpose:"A later layer may need a smaller spatial summary or an exact output size. Pooling combines regions within each channel. Adaptive pooling chooses those regions from the requested output size rather than a fixed step alone.",sources:"This task is \(t.title). A channel is processed separately for each observation; a two-dimensional channel has height and width. Average uses a region's values and divisor; Max selects a winner and may expose its original position. Adjacent adaptive regions can share boundary inputs.",wiring:guide.steps[0],controls:guide.steps[1],question:"Why can neighboring outputs depend on the same source cell? Which positions enter the divisor when averaging near padding? An exposed winning index is a position, not another measured feature.")
        }
        if let t=PoolingLearningTask(rawValue:operation) {
            return .init(purpose:t.isAverage ? "Average pooling summarizes nearby values. At a boundary, which positions count in the divisor matters as much as the sum." : "Max pooling keeps a local winner in each window. Its winning position explains which input value was retained; repeated use of a winner affects its measured influence.",sources:"This task is \(t.title). Channels are separate fields; spatial directions run along a line, a map or a volume. A window moves by Stride. Padding declares boundary positions, and a partial final window may contain fewer positions.",wiring:guide.steps[0],controls:guide.steps[1]+" "+guide.steps[2].components(separatedBy:"Check construction").first!,question:t.isAverage ? "Why can a partial boundary window have a different divisor? Which declared padding positions should count?":"What happens when two windows select the same source? How can you trace the winning index back to its channel?")
        }
        if let t=ConvolutionLearningTask(rawValue:operation) {
            return .init(purpose:t.isTransposed ? "A transposed convolution spreads a learned local window from each input position and adds overlapping contributions. It controls output geometry; it is not a general inverse that recovers an original image." : "A convolution applies the same learned window at many positions. Sharing that window lets a model respond to a local pattern wherever it appears, rather than learning a separate weight set for every location.",sources:"This task is \(t.title), with \(t.dimensions) spatial direction(s) and two input/output channels. A channel is one measurement field. Kernel size describes the local window; Stride moves it; Dilation spaces its selected cells. The checker supplies the window's weights and bias and varies input values. This is a mathematical construction, not training on photographs.",wiring:"Add Input, Convolution and Model Output. The restricted palette provides the \(t.isTransposed ? "transposed":"standard") \(t.dimensions)D operation permitted by this task. Connect Input.out → Convolution.in and Convolution.out → Model Output.in.",controls:guide.steps[1],question:t.isTransposed ? "Where do two contributions overlap, and why are they added? Why does output padding choose extent without restoring lost source information?":"Why does the same kernel influence several output positions? How do zero padding and a larger stride change the positions visited?")
        }
        if let t=ConfigurableActivationLearningTask(rawValue:operation) {
            return .init(purpose:"A nonlinear activation changes how a feature passes through the model. \(t.title) changes each number independently; it does not mix observation rows or normalize a group into probabilities.",sources:"Each observation has two rows of three numbers. Values can be positive, negative or zero. The checker supplies them; configure the permitted Activation function and its relevant controls rather than entering expected outputs.",wiring:"Add Input, Activation and Model Output. The restricted palette selects this task's function. Connect Input.out → Activation.in and Activation.out → Model Output.in.",controls:guide.steps[1],question:"Predict what happens to a negative value and to zero. Which function setting changes that response? Why should changing one feature leave the other features' direct outputs untouched?")
        }
        if let t=RemainingActivationLearningTask(rawValue:operation) {
            let purpose=t.isDropout ? "Dropout temporarily removes some measurements during training. It helps a model avoid depending on one exact collection of features; evaluation uses the full signal." : t.isPReLU ? "PReLU learns how much of a negative value to retain. A shared slope and separate channel slopes represent different parameter-sharing choices." : "LogSoftmax expresses a group's relative score shares on a logarithmic scale. Values in one group compete; it is not an independent transform of each score."
            return .init(purpose:purpose,sources:"This task is \(t.title). The checker supplies the input arrays and the requested training/evaluation context. \(t.isDropout ? "A drop probability is a chance per value, not a guarantee that exactly that percentage disappears. Evaluation draws no new removal mask." : t.isPReLU ? "The negative slopes are explicit learned parameters in this exercise; their measured influence is separate from input influence." : "Keep each observation separate and choose the sample direction whose values should compete.")",wiring:guide.steps[0],controls:guide.steps[1],question:t.isDropout ? "Why should training and evaluation differ? Why do runtime, device, seed and call order matter to an exact removal pattern?":t.isPReLU ? "When should two features share one negative slope? How does a channel's slope affect its negative and positive inputs differently?":"Which values compete in one group? Why is a logarithmic share different from a raw score or an ordinary probability?")
        }
        if operation==LazyLinearAssessment.operation {
            return .init(purpose:"A model builder may not know the incoming feature width until the previous layer is connected. Linear can infer that width once, then keep the same created weights for repeated execution and reload.",sources:"The input has two groups of three measurements per observation. The task asks for four output features per group, giving sample shape [2, 4]. Inference determines the input width, not the observation count. This check measures initialization/state behavior, not trained prediction quality.",wiring:"Add Input, Linear and Model Output. The restricted palette provides the inferred-width variant. Connect Input.out → Linear.in and Linear.out → Model Output.in.",controls:"Set Output features to 4 and choose whether to learn bias. Keep the two sample groups separate; do not flatten them into six incoming features.",question:"When should the weights be created? Why must repeating or reopening the same compatible calculation retain them instead of drawing fresh values?")
        }
        if ["softmax-last-axis","softmax-first-sample-axis"].contains(operation) {
            let last=operation=="softmax-last-axis"
            return .init(purpose:"Softmax turns a group of scores into positive shares adding to one. A larger score gets a larger share, and changing one score changes the other shares in that group.",sources:"Each observation has two rows of three scores. This task compares \(last ? "the three scores within each row":"the two scores within each column"). Scores from different observations must never compete. These shares are not automatically well-calibrated probabilities of a real-world outcome.",wiring:"Add Input, Activation and Model Output. The restricted palette selects Softmax. Connect Input.out → Activation.in and Activation.out → Model Output.in.",controls:"Set Normalization axis to \(last ? "-1":"1"). \(last ? "-1 means the last direction, so each three-score row is one group.":"1 is the first sample direction, so each two-score column is one group.")",question:"Which output shares should add to one? Why would summing the entire two-by-three array answer a different question? Softmax does not fix arbitrary unstable training.")
        }
        if ["layer-norm-rows","layer-norm-sample","layer-norm-affine"].contains(operation) {
            let affine=operation=="layer-norm-affine",whole=operation=="layer-norm-sample"
            return .init(purpose:"Layer normalization compares values within one observation with their group's average and spread. Selecting trailing dimensions decides which values share that calculation.",sources:"Each observation is a two-by-three table. This task normalizes \(whole ? "all six values together":"each three-value row separately"). It never learns a dataset-wide average from other observations. Optional learned scale and bias adjust the normalized values; they are not the measured group statistics.",wiring:"Add Input, Normalization and Model Output. The restricted palette selects Layer normalization. Connect Input.out → Normalization.in and Normalization.out → Model Output.in.",controls:"Set Trailing sample dimensions to \(whole ? "[2, 3]":"[3]") and Epsilon to 0.125. "+(affine ? "Enable learned scale and bias. In the parameter editor, enter scale [0.5, -1, 2] and bias [1, -0.5, 0.25]. Enable Inspect this component’s parameter gradients." : "Disable learned scale and bias."),question:"Which values affect the average for one output? How does this differ from Preprocess fitting statistics from a Training table? Epsilon stabilizes the division; it is not a learned replacement value.")
        }
        if let t=EmbeddingLearningTask(rawValue:operation) {
            let policy:String
            if operation=="embedding-padding-frequency" {policy="Set Padding row to 0 and enable Scale gradients by frequency. Leave Maximum norm unset."}
            else if operation=="embedding-renormalize" {policy="Leave Padding row unset, disable Scale gradients by frequency and set Maximum norm to 1 with Norm order 2."}
            else {policy="Leave Padding row and Maximum norm unset, disable Scale gradients by frequency and keep Norm order 2."}
            let controls="Set Table rows to 4 and Vector dimensions to 3. Keep Sparse gradients and Freeze learned weights disabled. "+policy
            return .init(purpose:"A category ID can select a learned vector without treating the ID as a numeric magnitude. Embedding is a shared lookup table: repeated IDs select the same row.",sources:"This task is \(t.title). The checker supplies whole-number category selectors and a varied four-row table with three values per row. Each selected row adds a final vector direction. The IDs themselves are not continuous values to differentiate.",wiring:"Add the supplied category Input, Embedding and Model Output. Connect the selectors to Embedding's input and its out to Model Output.in. The checker supplies the lookup table; do not type expected row values.",controls:controls,question:"Why do repeated IDs reuse one row? How does a reserved padding row differ from an unknown category? Which selected rows can a maximum-norm policy change?")
        }
        return nil
    }
    static func steps(_ operation:String)->[LessonContentStep]? {
        guard let copy=task(operation) else {return nil}
        let isBlock=ModuleCompositionLearningTask(rawValue:operation) != nil
        return [
            .init(id:"goal",title:"Meet the construction",blocks:[
                .init(id:"goal.body",kind:.explanation,title:"Understand the idea",text:copy.purpose),
                .init(id:"goal.sources",kind:.explanation,title:"Understand the supplied data",text:copy.sources),
                .init(id:"goal.context",kind:.callout,title:"This assessment's canvas",text:isBlock ? "The supplied Block model is already present. Its restricted editors measure reuse and structure; this is not an ordinary workflow training run." : "A fresh task starts with an empty, restricted canvas. Add the permitted boundaries and operation. The family placement selects the method permitted by this task; configure the fields actually shown for that method. The checker supplies input numbers when you submit.")]),
            LessonContent.step("build.0","Connect the calculation",copy.wiring,kind:.canvasAction),
            LessonContent.step("build.1","Configure this task",copy.controls+"\n\nApply pending fields before submitting. Planned shapes and declared roles are not captured execution values.",kind:.canvasAction),
            LessonContent.step("build.2","Predict before submitting",copy.question,kind:.question),
            LessonContent.step("check","Submit and read the feedback","Choose Submit assessment in Check your construction. The checker measures this task on independent inputs; it records relevant output, influence and state criteria automatically. Influence, or a gradient, describes how a small change affects the result. No handwritten derivatives or typed answers are required.\n\nPrivate fixture tables stay hidden in Assessment. Use measured criteria feedback to repair the indicated controls or connections. Unavailable runtime, cancellation and incorrect mathematics are different outcomes. A current passing assessment and saved receipt establish completion; editing makes a previous result historical.",kind:.observation)
        ]
    }
}
